330	            self.apply_outcome(outcome, in_flight.decode_reqs, config, ledger, spec_decode)?;
331	            self.in_flight = None;
332	            return Ok(());
333	        }
334	
335	        let Some(plan) = self.worker.plan_step()? else {
336	            return Ok(());
337	        };
338	        let step_id = plan.id();
339	        let shape = plan.shape();
340	        let estimate = self.profile.estimate_step(shape)?;
341	        for &request_id in plan.admitted() {
342	            let request = self
343	                .requests
344	                .get_mut(&request_id)
345	                .with_context(|| format!("missing profiled request {request_id}"))?;
346	            ledger.admit(request_id);
347	            if request
348	                .prompt_echo
349	                .as_ref()
350	                .is_some_and(|echo| echo.ids.is_empty())
351	            {
352	                ledger.echo_prompt(
353	                    request_id,
354	                    request
355	                        .prompt_echo
356	                        .take()
357	                        .expect("empty prompt echo was checked above"),
358	                );
359	            }
360	        }
361	        let ready_at = Instant::now()
362	            .checked_add(duration_from_us(estimate.duration_us))
363	            .context("profiled worker step deadline overflow")?;
364	        self.in_flight = Some(ProfiledInFlight {
365	            step_id,
366	            ready_at,
367	            decode_reqs: plan.decode().len(),
368	        });
369	        Ok(())
370	    }
371	
372	    fn drain_submissions(
373	        &mut self,
374	        config: &SimulatedEngineConfig,
375	        queued: &mut Vec<QueuedRequest>,
376	        ledger: &mut RequestLedger,
377	        prefix: &mut PrefixCacheTally,
378	    ) -> Result<()> {
379	        for QueuedRequest { id, request } in std::mem::take(queued) {
380	            if ledger.is_aborted(id) {
381	                ledger.retire(id);
382	                continue;
383	            }
384	            let prompt_tokens = u32::try_from(request.prompt_tokens.len())
385	                .context("profiled request prompt length exceeds u32")?;
386	            let output_token_count = planned_completion_len(config, request.max_tokens);
387	            let output_token_count_u64 = u64::try_from(output_token_count)
388	                .context("profiled output length overflows u64")?;
389	            if let Some(rejection) = self.worker.preflight(prompt_tokens, output_token_count_u64) {
390	                ledger.reject(id, reject_reason(rejection, &request));
391	                continue;
392	            }
393	            // Admitted: the same shared tally the legacy lane uses, so the
394	            // profiled lane does not report zeros for lookups it performed.
395	            prefix.note(config.prefix_cache, &request);
396	            let (mut completion_tokens, finish_reason) =
397	                planned_completion(config, &request.prompt_tokens, request.max_tokens);
398	            completion_tokens.reverse();
399	            let output_tokens =
400	                u32::try_from(completion_tokens.len()).context("profiled output exceeds u32")?;
401	            match self.worker.submit(WorkerRequest {
402	                id,
403	                prompt_tokens,
404	                output_tokens,
405	            })? {
406	                SubmissionResult::Queued => {
407	                    let previous = self.requests.insert(
408	                        id,
409	                        ProfiledRequest {
410	                            completion_tokens,
411	                            finish_reason,
412	                            logprobs: request.logprobs,
413	                            prompt_echo: request
414	                                .prompt_logprobs
415	                                .map(|top_k| logprobs::prompt(&request.prompt_tokens, top_k)),
416	                        },
417	                    );
418	                    ensure!(
419	                        previous.is_none(),
420	                        "profiled request metadata was duplicated"
421	                    );
422	                }
423	                SubmissionResult::Finished => {
424	                    ledger.admit(id);
425	                    if let Some(top_k) = request.prompt_logprobs {
426	                        ledger.echo_prompt(id, logprobs::prompt(&request.prompt_tokens, top_k));
427	                    }
428	                    ledger.finish(id, finish_reason);
429	                }
430	                SubmissionResult::Rejected(rejection) => {
431	                    ledger.reject(id, reject_reason(rejection, &request));
432	                }
433	            }
434	        }

586	            limit: max_num_batched_tokens as usize,
587	        },
588	    }
589	}
