607	    fn park_if_waiting(&self) {
608	        let Some(next) = self.running.iter().map(|r| r.next_token_at).min() else {
609	            return;
610	        };
611	        let now = Instant::now();
612	        if next <= now {
613	            return;
614	        }
615	        std::thread::sleep((next - now).min(WAIT_SLICE));
616	    }
617	}
